-- 모아루니: 사진 주소를 줄인 사본(opt/)으로 바꾸기 (원본 파일은 저장소에 그대로 남음)
create temp table _img_map(old text primary key, new text);
update public.products p set main_image = m.new from _img_map m where p.main_image = m.old;
update public.products p set sub_images = (select string_agg(coalesce(m.new, trim(x)), ',' order by ord) from unnest(string_to_array(p.sub_images, ',')) with ordinality as t(x, ord) left join _img_map m on m.old = trim(t.x)) where p.sub_images is not null and exists (select 1 from _img_map m where p.sub_images like '%' || m.old || '%');
update public.notices n set image_url = m.new from _img_map m where n.image_url = m.old;
select (select count(*) from public.products where main_image like '%/products/opt/%') as 대표사진_줄임, (select count(*) from public.products where sub_images like '%/products/opt/%') as 추가사진_줄임, (select count(*) from public.notices where image_url like '%/products/opt/%') as 배너팝업_줄임;
